export default function({$,$$,K,html,raw,put,S,opts,fmt,api}){async function checkout(){const id=+new URLSearchParams(location.search).get('id');let b;try{b=(await api('GET','bookings/'+id)).data}
catch(e){put($('#main'),html`<h1 class="u3">Booking not found</h1><p class="err" role="alert">${e.message}</p><a class="btn" href="bookings.html">My bookings</a>`);return}
if(b.booking_status==='confirmed'){location=`ticket.html?id=${id}`;return}
const show=x=>{$$('[data-st]').forEach(p=>p.classList.toggle('hid',p.dataset.st!=x))};put($('#sum'),html`<b>${b.operator_name}</b><br>${b.origin} → ${b.destination}<br>${fmt.date(b.departure_at)} · ${fmt.time(b.departure_at)}<br>${b.seats} seat${b.seats>1?'s':''} · ${b.passenger_name||''}<div class="tot">${K(b.total_amount)}</div><span class="mu">Reference ${b.booking_reference}</span>`);$('#amt').textContent=K(b.total_amount);const end=b.hold_expires_at?new Date(b.hold_expires_at).getTime():0;let timer;const tick=()=>{const left=Math.max(0,Math.round((end-Date.now())/1000));$('#hold').textContent=left>0?`Seats held for ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`:'Hold ended';if(left<=0&&end){clearInterval(timer);put($('[data-st=""]'),html`<p class="err" role="alert">The 15-minute hold has ended and the seats were released. <a href="index.html">Search again</a></p>`)}};if(b.booking_status!=='pending'){put($('[data-st=""]'),html`<p class="err" role="alert">This booking is ${b.booking_status}. <a href="index.html">Search again</a></p>`)}
else{tick();timer=setInterval(tick,1000)}
$('#pay').onsubmit=async e=>{e.preventDefault();show('p');const method=($('input[name=m]:checked')||{}).value||'mtn_momo';try{await api('POST',`bookings/${id}/payment`,{method,simulate_failure:$('#fail').checked});clearInterval(timer);show('s');setTimeout(()=>{location=`ticket.html?id=${id}`},900);}catch(err){if(err.status===409){put($('[data-st=""]'),html`<p class="err" role="alert">${err.message} <a href="index.html">Search again</a></p>`);show('');clearInterval(timer);return}
show('f');}
};$('#retry').onclick=()=>{$('#fail').checked=false;show('')};}
return checkout;}